<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class FacilityResourceController extends Controller{
private function ok(Request $r){$u=$r->user();abort_unless($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('facility_head')||$u->canDo('facility.stock')||$u->canDo('facility.manage'),403);}
public function stock(Request $r){$this->ok($r);$rows=DB::table('facility_stock_items')->orderBy('name')->get();return view('facility.stock',compact('rows'));}
public function item(Request $r){$this->ok($r);$d=$r->validate(['name'=>'required|string|max:500','unit'=>'required|string|max:30','minimum_quantity'=>'required|numeric|min:0','unit_cost'=>'nullable|numeric|min:0','storage_location'=>'nullable|string|max:255']);DB::table('facility_stock_items')->insert($d+['quantity'=>0,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function movement(Request $r,$item){$this->ok($r);$d=$r->validate(['type'=>'required|in:receipt,issue,writeoff,adjustment','quantity'=>'required|numeric|not_in:0','unit_cost'=>'nullable|numeric|min:0','document_number'=>'nullable|string|max:255','reason'=>'nullable|string|max:3000','facility_work_order_id'=>'nullable|exists:facility_work_orders,id']);DB::transaction(function()use($item,$d,$r){$x=DB::table('facility_stock_items')->where('id',$item)->lockForUpdate()->first();abort_if(!$x,404);$delta=$d['type']==='receipt'?abs($d['quantity']):-abs($d['quantity']);if($d['type']==='adjustment')$delta=$d['quantity'];abort_if($x->quantity+$delta<0,422,'Недостаточно материала на складе');DB::table('facility_stock_items')->where('id',$item)->update(['quantity'=>$x->quantity+$delta,'unit_cost'=>$d['unit_cost']??$x->unit_cost,'updated_at'=>now()]);DB::table('facility_stock_movements')->insert($d+['facility_stock_item_id'=>$item,'quantity'=>$delta,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);});return back();}
public function meters(Request $r){$this->ok($r);$meters=DB::table('facility_meters as m')->join('facility_buildings as b','b.id','=','m.facility_building_id')->select('m.*','b.name as building_name')->get();foreach($meters as $m){$m->readings=DB::table('facility_meter_readings')->where('facility_meter_id',$m->id)->orderByDesc('reading_on')->limit(12)->get();$two=$m->readings->take(2);$m->consumption=$two->count()===2?round(($two[0]->value-$two[1]->value)*$m->multiplier,3):null;}$buildings=DB::table('facility_buildings')->get();return view('facility.meters',compact('meters','buildings'));}
public function meter(Request $r){$this->ok($r);$d=$r->validate(['facility_building_id'=>'required|exists:facility_buildings,id','resource'=>'required|in:electricity,cold_water,hot_water,heating,gas,other','name'=>'required|string|max:500','serial_number'=>'nullable|string|max:255','unit'=>'required|string|max:30','multiplier'=>'required|numeric|min:0.0001']);DB::table('facility_meters')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function reading(Request $r,$meter){$this->ok($r);$d=$r->validate(['reading_on'=>'required|date','value'=>'required|numeric|min:0']);DB::table('facility_meter_readings')->updateOrInsert(['facility_meter_id'=>$meter,'reading_on'=>$d['reading_on']],['value'=>$d['value'],'recorded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}